# 比べる項目の名前と、メッセージに書く名前
LABELS = {
    "type": "型",
    "null": "NULL を許可するか",  # 英字で始まるので、メッセージでは「の」との間に空白が入る
    "default": "デフォルト値",
    "references": "外部キーの参照先",
